$ok=(string)($_SESSION['flash_success_ausencias_colaboradores']??'');$erro=(string)($_SESSION['flash_error_ausencias_colaboradores']??'');unset($_SESSION['flash_success_ausencias_colaboradores'],$_SESSION['flash_error_ausencias_colaboradores']);
$st=$pdo->prepare("SELECT s.*,p.nome_completo colaborador_nome FROM colaborador_solicitacoes_ausencia s INNER JOIN colaboradores c ON c.id=s.colaborador_id AND c.empresa_id=s.empresa_id INNER JOIN pessoas p ON p.id=c.pessoa_id AND p.empresa_id=s.empresa_id WHERE s.empresa_id=:e ORDER BY FIELD(s.status,'pendente','aprovada','rejeitada','cancelada'),s.inicio");$st->execute([':e'=>$empresa]);$lista=$st->fetchAll(PDO::FETCH_ASSOC);
$id=filter_input(INPUT_GET,'detalhe',FILTER_VALIDATE_INT);$det=null;$hist=[];$coment=[];
if(is_int($id)){foreach($lista as$x)if((int)$x['id']===$id){$det=$x;break;}if($det){$st=$pdo->prepare("SELECT h.*,COALESCE(adm.nome_completo,pc.nome_completo,u.email) usuario_nome FROM colaborador_solicitacao_ausencia_historico h INNER JOIN usuarios u ON u.id=h.usuario_id LEFT JOIN administradores adm ON adm.usuario_id=u.id AND adm.empresa_id=:e LEFT JOIN colaboradores col ON col.usuario_id=u.id AND col.empresa_id=:e LEFT JOIN pessoas pc ON pc.id=col.pessoa_id AND pc.empresa_id=:e WHERE h.solicitacao_id=:id ORDER BY h.criado_em,h.id");$st->execute([':e'=>$empresa,':id'=>$id]);$hist=$st->fetchAll(PDO::FETCH_ASSOC);$st=$pdo->prepare("SELECT c.*,COALESCE(adm.nome_completo,u.email) usuario_nome FROM colaborador_solicitacao_ausencia_comentarios c INNER JOIN usuarios u ON u.id=c.usuario_id LEFT JOIN administradores adm ON adm.usuario_id=u.id AND adm.empresa_id=:e WHERE c.solicitacao_id=:id ORDER BY c.criado_em,c.id");$st->execute([':e'=>$empresa,':id'=>$id]);$coment=$st->fetchAll(PDO::FETCH_ASSOC);}}
function caf(string$d):string{return(new DateTimeImmutable($d))->format('d/m/Y H:i');}function cas(string$s):string{return match($s){'pendente'=>'Pendente','aprovada'=>'Aprovada','rejeitada'=>'Rejeitada','cancelada'=>'Cancelada',default=>$s};}
