<section class="app-card mb-4"><div class="app-card-header"><h2>Solicitações</h2></div><div class="app-card-body p-0"><?php if(!$lista):?><div class="app-empty-state"><p>Nenhuma solicitação encontrada.</p></div><?php else:?><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Colaborador</th><th>Período</th><th>Tipo</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($lista as$s):?><tr><td><?=htmlspecialchars((string)$s['colaborador_nome'],ENT_QUOTES,'UTF-8')?></td><td><?=caf((string)$s['inicio'])?> – <?=caf((string)$s['fim'])?></td><td><?=htmlspecialchars((string)$s['tipo'],ENT_QUOTES,'UTF-8')?></td><td class="ausencia-status ausencia-status--<?=$s['status']?>"><?=cas((string)$s['status'])?></td><td><a class="btn btn-sm btn-outline-primary" href="?detalhe=<?=(int)$s['id']?>">Detalhes</a></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></div></section>
<?php if($det):?><section class="app-card"><div class="app-card-header"><h2>Detalhes #<?=(int)$det['id']?></h2></div><div class="app-card-body"><p><strong>Colaborador:</strong> <?=htmlspecialchars((string)$det['colaborador_nome'],ENT_QUOTES,'UTF-8')?><br><strong>Período:</strong> <?=caf((string)$det['inicio'])?> – <?=caf((string)$det['fim'])?><br><strong>Status:</strong> <?=cas((string)$det['status'])?><br><strong>Motivo:</strong> <?=htmlspecialchars((string)($det['motivo']?:'—'),ENT_QUOTES,'UTF-8')?></p>
<?php if($det['status']==='pendente'):?><form method="post" action="api/ausencias-colaboradores.php"><input type="hidden" name="csrf_token" value="<?=$csrf?>"><input type="hidden" name="solicitacao_id" value="<?=(int)$det['id']?>"><div class="form-group"><label>Observação da decisão</label><textarea name="observacao_decisao" class="form-control"></textarea></div><button name="acao" value="aprovar" class="btn btn-success">Aprovar</button> <button name="acao" value="rejeitar" class="btn btn-outline-danger">Rejeitar</button></form><?php elseif($det['status']==='aprovada'):?><form method="post" action="api/ausencias-colaboradores.php"><input type="hidden" name="csrf_token" value="<?=$csrf?>"><input type="hidden" name="acao" value="cancelar_aprovacao"><input type="hidden" name="solicitacao_id" value="<?=(int)$det['id']?>"><div class="form-group"><label>Motivo para cancelar a aprovação</label><textarea name="motivo_cancelamento" class="form-control" required></textarea></div><button class="btn btn-outline-danger">Cancelar aprovação</button></form><?php endif;?>
<h3 class="h5 mt-4">Histórico</h3><ul class="ausencia-timeline"><?php foreach($hist as$h):?><li><strong><?=htmlspecialchars(str_replace('_',' ',(string)$h['acao']),ENT_QUOTES,'UTF-8')?></strong><small><?=htmlspecialchars((string)$h['usuario_nome'].' • '.caf((string)$h['criado_em']),ENT_QUOTES,'UTF-8')?></small><?php if($h['detalhes']):?><div><?=nl2br(htmlspecialchars((string)$h['detalhes'],ENT_QUOTES,'UTF-8'))?></div><?php endif;?></li><?php endforeach;?></ul>
<h3 class="h5 mt-4">Comentários internos</h3><?php foreach($coment as$c):?><div class="ausencia-comment"><strong><?=htmlspecialchars((string)$c['usuario_nome'],ENT_QUOTES,'UTF-8')?></strong> <small><?=caf((string)$c['criado_em'])?></small><div><?=nl2br(htmlspecialchars((string)$c['comentario'],ENT_QUOTES,'UTF-8'))?></div></div><?php endforeach;?><form method="post" action="api/ausencias-colaboradores.php" class="mt-3"><input type="hidden" name="csrf_token" value="<?=$csrf?>"><input type="hidden" name="acao" value="comentar"><input type="hidden" name="solicitacao_id" value="<?=(int)$det['id']?>"><textarea name="comentario" class="form-control mb-2" required></textarea><button class="btn btn-outline-primary">Adicionar comentário</button></form></div></section><?php endif;?></main><?php require __DIR__.'/partials/footer.php';?>
